+  const rotors = [];
+  for (const [x, z] of [[-0.57, -0.4], [0.57, -0.4], [-0.57, 0.4], [0.57, 0.4]]) {
+    addBox(g, 0.62, 0.055, 0.07, x * 0.62, 1.62, z * 0.62, shell);
+    const rotor = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.26, 0.025, 12), darkMat);
