+}
+
+function releaseObstacle(o) {
+  o.active = false;
+  o.group.visible = false;
+}
+
+/* -------------------------------------------------------------------------
+   Coins
+   ------------------------------------------------------------------------- */
+const coinGeo = new THREE.CylinderGeometry(0.33, 0.33, 0.065, 20);
+const coinInnerGeo = new THREE.CylinderGeometry(0.22, 0.22, 0.075, 14);
+const coinMat = new THREE.MeshStandardMaterial({
+  color: 0xffc531,
+  emissive: 0xffa000,
+  emissiveIntensity: 1.45,
+  roughness: 0.24,
+  metalness: 0.78,
+});
+const coinInnerMat = new THREE.MeshStandardMaterial({
+  color: 0x8a4c00,
+  emissive: 0xffd34e,
+  emissiveIntensity: 0.75,
+  roughness: 0.35,
+  metalness: 0.65,
+});
+const coinPool = [];
+const activeCoins = [];
+
+function buildCoin() {
+  const g = new THREE.Group();
+  const disc = new THREE.Mesh(coinGeo, coinMat);
+  disc.rotation.x = Math.PI / 2;
+  g.add(disc);
+  const inner = new THREE.Mesh(coinInnerGeo, coinInnerMat);
+  inner.rotation.x = Math.PI / 2;
